/**
 * The equipment3d registry contract (plan §4.3). Entries are keyed by catalogue definition id and
 * generated by tools/blender/pack_models.py from each model's meta.json; never edit
 * registry.json by hand.
 *
 * Coordinates are model-local millimetres: x to the viewer's right, y away from the default
 * viewer, z up, with the origin at the footprint centre on the bench plane. The viewer converts
 * them to three.js Y-up; runtime bench units are converted only in adapters/benchCoordinates.
 */
export type Vec3Mm = number[];

export type Equipment3DFootprint =
  | { shape: "circle"; radius: number }
  | { shape: "rect"; width: number; depth: number };

export interface Equipment3DPour {
  /** The point liquid leaves the source, model-local. */
  lipMm: Vec3Mm;
  /** Tilt used when the committed pour animates (handoff §5.7). */
  tiltDeg: number;
  /** "pour" tips from a lip; "squeeze-jet" is a wash bottle's delivery tube. */
  style?: "pour" | "squeeze-jet";
  tipDirection?: Vec3Mm;
}

export interface Equipment3DFill {
  /** Inner surface-of-revolution profile, [radius, height] pairs in mm, height increasing. */
  innerProfileMm?: number[][];
  /** Rectangular inner cavity (a cuvette), used instead of a profile. */
  innerBoxMm?: { width: number; depth: number; floorZ: number; topZ: number };
  /** Equals the catalogue capacity; the profile must hold at least this much. */
  capacityMl: number;
  meniscus: "concave" | "convex" | "flat";
}

export interface Equipment3DGraduations {
  unit: "mL";
  minor: number;
  major: number;
  maxMl: number;
}

/** Where a powder or other solid heap rests inside or on the item (plan §2.6: powder when solid). */
export interface Equipment3DSolidRest {
  centreMm: Vec3Mm;
  radiusMm: number;
}

/** A calibration ring (a volumetric flask): the height at which the item holds `ml`. */
export interface Equipment3DCalibration {
  ml: number;
  heightMm: number;
}

/** A zone anchor, keyed by semantic zone id from src/domain/interactionZones.ts. */
export interface Equipment3DAnchor {
  positionMm: Vec3Mm;
  /** Rotation of the seated child about z, in degrees. */
  yawDeg?: number;
  /** Tilt of the seated child's top toward its own +y before the yaw, in degrees (a rod resting on a rim). */
  leanDeg?: number;
}

/** A display surface; `policy` names an entry in displayPolicies.json. */
export interface Equipment3DDisplay {
  id: string;
  policy: string;
  /** Centre of the display face, model-local. */
  centreMm: Vec3Mm;
  sizeMm: number[];
  /** Unit outward normal of the display face, model-local. */
  normalMm: Vec3Mm;
}

/**
 * A control on an instrument that the viewer operates, such as a balance's TARE key. `objects` are
 * the model's node names that form it; pressing it performs the technique step for `operation`.
 */
export interface Equipment3DControl {
  id: string;
  /** "zero": a balance's TARE; "set-temperature": an oven's setting dial; "door": an oven's door (Pack 2). */
  operation: "zero" | "set-temperature" | "door";
  label: string;
  objects: string[];
  centreMm: Vec3Mm;
  sizeMm: number[];
  normalMm: Vec3Mm;
}

export interface Equipment3DProvenance {
  blender: string;
  generator: string;
  sourceHash: string;
}

export interface Equipment3DEntry {
  definitionId: string;
  model: string;
  thumbnail: string;
  footprintMm: Equipment3DFootprint;
  grip: { heightMm: number };
  pour?: Equipment3DPour;
  fill?: Equipment3DFill;
  graduations: Equipment3DGraduations | null;
  calibration?: Equipment3DCalibration;
  /** The scenery id that holds this item upright when it stands on the bench (decision D9). */
  requiresSupport?: string;
  /**
   * The scenery id that lies flat under this item when it lies on the bench (decision D9; a chromatography strip's
   * white tile, decided 2026-10-11). Unlike a support, it stays where the item lay while the item is elsewhere on
   * the bench (a strip hanging in its chamber); the item rests on its seat.
   */
  restsOn?: string;
  solidRest?: Equipment3DSolidRest;
  /**
   * How the item rests on the bench when its model is authored in its working pose (decided
   * 2026-09-26): a funnel, modelled upright to seat by its stem tip, rests mouth-down; a pipette,
   * modelled tip-down, lies flat. Turned `rollDeg` about its x axis, lifted `liftMm`, and moved so its
   * footprint centres on its bench point (`shiftMm`, where its origin lies from that point). It is
   * carried and seated upright.
   */
  benchRest?: { rollDeg: number; liftMm: number; shiftMm: number[] };
  /** A pipette, carried upright and judged by its tip (its origin): it draws up and delivers liquid. */
  carriedByTip?: boolean;
  /**
   * An item drawn in one of several forms (Pack 2, decided 2026-10-05: a filter paper flat, folded or
   * opened into a cone): the model's node names for each form. One form shows at a time: the one its
   * seat takes (`formBySeat`), else the one the runtime records for it (`apparatusStates`), else
   * `defaultForm`. A form may have its own solid rest (`formSolidRest`).
   */
  forms?: Record<string, string[]>;
  defaultForm?: string;
  formBySeat?: Record<string, string>;
  formSolidRest?: Record<string, Equipment3DSolidRest>;
  /** Darkened and translucent while wet (a filter paper wetted, or holding a wet precipitate). */
  wetLook?: boolean;
  /**
   * A hinged door drawn open or closed from the runtime's apparatus state (Pack 2: the drying oven): its
   * node names, its hinge's vertical axis at [x, y] model-local mm, and how far it swings out toward the
   * viewer when `stateKey` reads "open".
   */
  doors?: Array<{ id: string; objects: string[]; hingeMm: number[]; openDeg: number; stateKey: string }>;
  /** A tool's working end, model-local mm (tongs' jaws, a scoop's end): where it is aimed when carried. */
  tipMm?: Vec3Mm;
  /**
   * Parts drawn by the runtime's apparatus state (Pack 2's Heat and Reweigh: a crucible's lid on or askew, a
   * burner's flame and air ports). The values of `stateKeys`, joined by "/", pick the parts shown; a value
   * not listed falls back to its first key's value alone, then to `default`. Every other listed part is hidden.
   */
  stateObjects?: Array<{ stateKeys: string[]; default: string; objects: Record<string, string[]> }>;
  /**
   * A chromatography strip's face (Pack 3a, decided 2026-10-10): modelled upright with its origin at the centre
   * of its bottom edge, `widthMm` across and `lengthMm` up, its printed face toward `normalMm`, the hanging hole's
   * centre `hole.centreZMm` above the bottom edge. Baseline, spots, front and bands are drawn on this face.
   */
  stripFace?: {
    widthMm: number;
    lengthMm: number;
    thicknessMm: number;
    normalMm: number[];
    hole: { centreZMm: number; radiusMm: number };
  };
  /**
   * A ruler's printed scale (Pack 3a): the zero on its measuring edge (`zeroMm`, model-local), the direction the
   * scale runs, its length and smallest division, so a strip's distances line up with the printed lines.
   */
  scaleMm?: { zeroMm: Vec3Mm; directionMm: number[]; lengthMm: number; minorMm: number };
  /** How far the lid rises when lifted from its seat before it is set aside (a chamber's cap and hook, Pack 3a). */
  liftedWithLidMm?: number;
  /** A dull red glow on these parts while `stateKey` reads true (a crucible under strong heating). */
  glow?: { stateKey: string; objects: string[] };
  /** Parts that flicker slightly while shown (a flame), except under reduced motion. */
  flicker?: string[];
  anchors: Record<string, Equipment3DAnchor>;
  displays: Equipment3DDisplay[];
  controls?: Equipment3DControl[];
  /** Named visual states (for example a stopper seated or removed); presentation only. */
  states: Record<string, unknown>;
  /** Visual-only bench scenery (decision D9): never an equipment instance, never selectable. */
  scenery?: boolean;
  /** For scenery: the catalogue definition it supports, and where that item's origin sits. */
  sceneryFor?: { definitionId: string; seatsMm: Vec3Mm[] };
  provenance: Equipment3DProvenance;
}

export interface Equipment3DRegistry {
  schema: string;
  generatedBy: string;
  coordinates: string;
  assetBase: string;
  entries: Equipment3DEntry[];
}
